<template><main class="model-page"><section class="hero"><div class="wrap"><NuxtLink to="/spec-library/mazak/cnc-lathes" class="back">← Mazak CNC Lathe Library</NuxtLink><div class="kicker">UMS MACHINERY SPECIFICATION LIBRARY</div><h1>Mazak Quick-Turn 10 Specifications</h1><p>Historical Mazak Quick-Turn 10 specifications organized by year, control and configuration from UMS machinery records.</p></div></section><section class="wrap section"><div class="warning"><strong>Historical specification information — not a machine-for-sale listing.</strong> Values below are tied to historical UMS records and may vary by machine, year and equipment.</div><h2>Historical Quick-Turn 10 Specifications by Year</h2><p>The Quick-Turn 10 designation spans substantially different machines in the UMS records, making the year and control especially important when researching specifications.</p><article v-for="c in configurations" :key="c.title" class="configuration"><div class="config-head"><div><div class="year">{{c.year}}</div><h3>{{c.title}}</h3><p><strong>Control:</strong> {{c.control}}</p></div><button class="copy" type="button" @click="copySpecs(c)">{{copied===c.title?'Copied!':'Copy Specifications'}}</button></div><div class="spec-grid"><div v-for="s in c.specs" :key="s.label" class="spec"><span>{{s.label}}</span><strong>{{s.value}}</strong></div></div><p v-if="c.note" class="note">{{c.note}}</p></article></section></main></template>
